-- 과제 6 DB 전용 일회성 migration. 적용 전 DB 백업 필수.
USE pds_diary;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(100) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE auth_sessions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,jti CHAR(36) NOT NULL UNIQUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_activity_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,idle_expires_at DATETIME NOT NULL,absolute_expires_at DATETIME NOT NULL,revoked_at DATETIME NULL,CONSTRAINT fk_session_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_session_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE plans ADD COLUMN owner_id BIGINT UNSIGNED NULL AFTER id,ADD CONSTRAINT fk_plan_owner FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE,ADD INDEX idx_plan_owner(owner_id);
CREATE TABLE daily_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_id BIGINT UNSIGNED NULL,record_date DATE NOT NULL,metric_name VARCHAR(120) NOT NULL,metric_unit VARCHAR(40) NOT NULL,metric_value DECIMAL(12,2) NULL,calculation_rule TEXT NOT NULL,plan_rule TEXT NOT NULL,note TEXT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_daily_owner FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT uq_daily_owner_date UNIQUE(owner_id,record_date),INDEX idx_daily_owner(owner_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE rule_changes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,owner_id BIGINT UNSIGNED NULL,changed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,before_rule TEXT NOT NULL,after_rule TEXT NOT NULL,reason TEXT NOT NULL,day1_record_id BIGINT UNSIGNED NOT NULL,day2_record_id BIGINT UNSIGNED NOT NULL,CONSTRAINT fk_rule_owner FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_rule_day1 FOREIGN KEY(day1_record_id) REFERENCES daily_records(id) ON DELETE CASCADE,CONSTRAINT fk_rule_day2 FOREIGN KEY(day2_record_id) REFERENCES daily_records(id) ON DELETE CASCADE,CONSTRAINT uq_rule_owner UNIQUE(owner_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- migration 후 앱에서 만드는 최초 계정이 owner_id IS NULL인 기존 자료를 transaction으로 인계한다.
